1	import { useCallback } from "react";
2	
3	import { ComposerForm, type ComposerPayload } from "./ComposerForm.tsx";
4	import { Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle } from "./Dialog.tsx";
5	
6	/** Payload the host receives when the composer saves. */
7	export type AnnotationComposerPayload = ComposerPayload;
8	
9	/**
10	 * Kinds the composer dialog supports. Selection-anchored kinds (`comment` /
11	 * `insertion` / `replacement`) render a quote block above the textarea; the
12	 * top-bar `global` kind has no anchor and so omits the quote.
13	 */
14	export type AnnotationComposerKind = "comment" | "insertion" | "replacement" | "global";
15	
16	interface KindSurface {
17	  title: string;
18	  /** Title shown when reopening the composer to edit an existing annotation. */
19	  editTitle: string;
20	  description: string;
21	  placeholder: string;
22	  /** Tailwind class applied to the anchored quote block; ignored when `global`. */
23	  quoteClass: string;
24	  /** Per-kind test ids so existing Playwright selectors keep resolving. */
25	  testIds: {
26	    /** Wraps the dialog content. */
27	    composer: string;
28	    /** Reused by `ComposerForm` for textarea / cancel / save buttons. */
29	    form: { textarea: string; cancel: string; save: string };
30	  };
31	}
32	
33	const kindSurface: Record<AnnotationComposerKind, KindSurface> = {
34	  comment: {
35	    title: "Comment on selection",
36	    editTitle: "Edit comment",
37	    description: "Add a comment to the selected text.",
38	    placeholder: "Comment on this selection… (Enter to save, Esc to cancel)",
39	    quoteClass: "border-anno-comment text-anno-comment bg-anno-comment/10",
40	    testIds: {
41	      composer: "annotation-composer",
42	      form: { textarea: "composer-textarea", cancel: "composer-cancel", save: "composer-save" },
43	    },
44	  },
45	  insertion: {
46	    title: "Insert after selection",
47	    editTitle: "Edit insertion",
48	    description: "Type the text you want to insert after the selection.",
49	    placeholder: "Insert text after this selection… (Enter to save, Esc to cancel)",
50	    quoteClass: "border-anno-insert text-anno-insert bg-anno-insert/10",
51	    testIds: {
52	      composer: "annotation-composer",
53	      form: { textarea: "composer-textarea", cancel: "composer-cancel", save: "composer-save" },
54	    },
55	  },
56	  replacement: {
57	    title: "Replace selection",
58	    editTitle: "Edit replacement",
59	    description: "Type the text you want to substitute for the selection.",
60	    placeholder: "Replace this selection with… (Enter to save, Esc to cancel)",
61	    quoteClass: "border-anno-replace text-anno-replace bg-anno-replace/10",
62	    testIds: {
63	      composer: "annotation-composer",
64	      form: { textarea: "composer-textarea", cancel: "composer-cancel", save: "composer-save" },
65	    },
66	  },
67	  global: {
68	    title: "Global comment",
69	    editTitle: "Edit global comment",
70	    description: "Leave feedback that isn't tied to a selection.",
71	    placeholder: "Global feedback on the plan… (Enter to save, Esc to cancel)",
72	    quoteClass: "",
73	    testIds: {
74	      composer: "global-comment-composer",
75	      form: {
76	        textarea: "global-composer-textarea",
77	        cancel: "global-composer-cancel",
78	        save: "global-composer-save",
79	      },
80	    },
81	  },
82	};
83	
84	/**
85	 * Whether the composer is authoring a new annotation (`create`) or editing an
86	 * existing one (`edit`). Edit mode swaps in the per-kind {@link KindSurface.editTitle}
87	 * and surfaces a visible header so the reviewer knows they are changing an
88	 * existing note rather than adding one.
89	 */
90	export type AnnotationComposerMode = "create" | "edit";
91	
92	/**
93	 * Resolve the dialog header for a kind + mode: edit mode shows the edit title
94	 * and an always-visible header; the anchored create surfaces hide their header
95	 * (the quote carries the context) while `global` keeps it.
96	 */
97	const headerFor = (
98	  surface: KindSurface,
99	  kind: AnnotationComposerKind,
100	  mode: AnnotationComposerMode
101	): { title: string; hidden: boolean } => {
102	  const isEdit = mode === "edit";
103	  return {
104	    title: isEdit ? surface.editTitle : surface.title,
105	    hidden: !isEdit && kind !== "global",
106	  };
107	};
108	
109	interface AnnotationComposerProps {
110	  /** Which authoring surface to render. `global` omits the quote block. */
111	  kind: AnnotationComposerKind;
112	  open: boolean;
113	  /** Authoring vs. editing an existing annotation. Defaults to `create`. */
114	  mode?: AnnotationComposerMode;
115	  /** Selected text rendered as a quote above the textarea. Required unless `kind === "global"`. */
116	  quote?: string;
