1	import { MarkdownPlugin } from "@platejs/markdown";
2	import { useEffect, useRef } from "react";
3	import { Plate, PlateContent, usePlateEditor } from "platejs/react";
4	import { AnnotationComposer } from "@symbiot/ui/components/AnnotationComposer";
5	
6	import { SymbiotEditorKit } from "../utils/kit.ts";
7	import { stampBlockLines } from "../utils/sourceLines.ts";
8	import { useTypingGuard } from "../utils/typingGuard.ts";
9	
10	import {
11	  useComposerController,
12	  useReadyHandle,
13	  useRemoveAnnotation,
14	  useTaskToggle,
15	  useToolbarHandlers,
16	  useUpdateAnnotation,
17	} from "./ReviewEditorAuthoring.tsx";
18	import { snapshotOf } from "./ReviewEditorPrune.tsx";
19	import { TaskToggleContext } from "./TaskToggleContext.ts";
20	import { useAnnotationState } from "./ReviewEditorState.tsx";
21	import { ToolbarButtons } from "./ReviewEditorToolbar.tsx";
22	import {
23	  type AnnotationHandleKind,
24	  type EditorSnapshot,
25	  type ReviewEditorHandle,
26	} from "./ReviewEditorTypes.tsx";
27	
28	// Re-export the public types so existing consumers keep importing them from
29	// `@symbiot/editor/components/ReviewEditor`. The internal `*Types.tsx` file is
30	// the source of truth.
31	export type { AnnotationHandleKind, EditorSnapshot, ReviewEditorHandle };
32	
33	/** Props accepted by {@link ReviewEditor}. */
34	interface ReviewEditorProps {
35	  /** Markdown of the plan version being reviewed. */
36	  markdown: string;
37	  /** Optional saved Plate value to hydrate the editor from (overrides markdown deserialize). */
38	  initialValue?: unknown[];
39	  /** Optional saved comment bodies to seed the discussion store. */
40	  initialBodies?: Map<string, string>;
41	  /** Optional saved comment images, keyed by comment id. */
42	  initialImages?: Map<string, string[]>;
43	  /** Optional saved per-comment `originalText` snapshots — drives drift detection. */
44	  initialCommentOriginalTexts?: Map<string, string>;
45	  /** Optional saved per-deletion `originalText` snapshots — drives drift detection. */
46	  initialSuggestionOriginalTexts?: Map<string, string>;
47	  /** Optional saved per-insertion `newText` map. */
48	  initialInsertionNewTexts?: Map<string, string>;
49	  /** Optional saved per-insertion image refs. */
50	  initialInsertionImages?: Map<string, string[]>;
51	  /** Optional saved per-insertion `contextText` snapshots — drives drift detection. */
52	  initialInsertionOriginalTexts?: Map<string, string>;
53	  /** Optional saved per-replacement `replacementText` map. */
54	  initialReplacementTexts?: Map<string, string>;
55	  /** Optional saved per-replacement image refs. */
56	  initialReplacementImages?: Map<string, string[]>;
57	  /** Optional saved per-replacement `originalText` snapshots — drives drift detection. */
58	  initialReplacementOriginalTexts?: Map<string, string>;
59	  /** Receives the imperative handle once Plate is constructed. */
60	  onReady?: (handle: ReviewEditorHandle) => void;
61	  /** Fires on every Plate editor change with a serializable snapshot. */
62	  onChange?: (snapshot: EditorSnapshot) => void;
63	  /** Fires when the inline annotation composer opens (true) or closes (false). */
64	  onComposerOpenChange?: (open: boolean) => void;
65	}
66	
67	/**
68	 * Read-only Plate editor that renders a markdown plan and lets the reviewer
69	 * drop anchored Comment / Deletion / Insertion / Replacement marks via a
70	 * floating selection toolbar. The editor stays `readOnly={true}`; marks are
71	 * applied programmatically through {@link applyAnnotation} via `editor.tf.*`
72	 * transforms, which bypass `contenteditable=false`.
73	 *
74	 * Insertion authoring shares the Comment composer's UX —
75	 * {@link AnnotationComposer} switches accent + labels based on `kind`.
76	 */
77	export const ReviewEditor = ({
78	  markdown,
79	  initialValue,
80	  initialBodies,
81	  initialImages,
82	  initialCommentOriginalTexts,
83	  initialSuggestionOriginalTexts,
84	  initialInsertionNewTexts,
85	  initialInsertionImages,
86	  initialInsertionOriginalTexts,
87	  initialReplacementTexts,
88	  initialReplacementImages,
89	  initialReplacementOriginalTexts,
90	  onReady,
91	  onChange,
92	  onComposerOpenChange,
93	}: ReviewEditorProps): React.ReactElement => {
94	  const containerRef = useRef<HTMLDivElement | null>(null);
95	  const { maps, setters } = useAnnotationState({
96	    initialBodies,
97	    initialImages,
98	    initialCommentOriginalTexts,
99	    initialSuggestionOriginalTexts,
100	    initialInsertionNewTexts,
101	    initialInsertionImages,
102	    initialInsertionOriginalTexts,
103	    initialReplacementTexts,
104	    initialReplacementImages,
105	    initialReplacementOriginalTexts,
106	  });
107	
108	  const editor = usePlateEditor({
109	    plugins: SymbiotEditorKit,
110	    value: (e): never => {
111	      if (initialValue !== undefined) return initialValue as never;
112	      const deserialized = e.getApi(MarkdownPlugin).markdown.deserialize(markdown);
113	      return stampBlockLines(markdown, deserialized) as never;
114	    },
115	  });
116	
117	  const { pending, setPending, onComposerSave, onComposerCancel } = useComposerController(
118	    editor,
119	    maps,
120	    setters,
121	    onChange
122	  );
123	
124	  useTypingGuard(containerRef);
125	
126	  const onRemoveAnnotation = useRemoveAnnotation(editor, maps, setters, onChange);
127	  const onUpdateAnnotation = useUpdateAnnotation(maps, setters);
